import { createHash } from "node:crypto";
import { readFileSync, readdirSync, statSync, writeFileSync } from "node:fs";
import { basename, dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import { RENDERED_FINDING_ADDENDA, RENDERED_INTERACTION_ADDENDA } from "./rendered-demo-addenda.registry.mjs";

const ROOT = dirname(fileURLToPath(import.meta.url));
const REPO = resolve(ROOT, "../../../..");
const argv = process.argv.slice(2);
const option = (name, fallback) => {
    const index = argv.indexOf(name);
    return index === -1 ? fallback : argv[index + 1];
};
const required = (name) => {
    const value = option(name, null);
    if (!value) throw new Error(`missing ${name} <path>`);
    return resolve(value);
};
const sha = (value) => createHash("sha256").update(value).digest("hex");
const fileSha = (path) => sha(readFileSync(path));
const json = (path) => JSON.parse(readFileSync(path, "utf8"));
const uniq = (items) => [...new Set(items)];
const countBy = (items, key) => Object.fromEntries(Object.entries(Object.groupBy(items, key)).map(([name, rows]) => [name, rows.length]));
const table = (headers, rows) => [
    `| ${headers.join(" | ")} |`,
    `| ${headers.map(() => "---").join(" | ")} |`,
    ...rows.map((row) => `| ${row.map((cell) => String(cell).replaceAll("|", "\\|").replaceAll("\n", " ")).join(" | ")} |`),
].join("\n");

const inputPaths = {
    desktop: required("--desktop"),
    mobile: required("--mobile"),
    extra: required("--extra"),
};
const contactDirs = {
    desktop: resolve(option("--desktop-contacts", "/tmp/glass-bi-contact")),
    mobile: resolve(option("--mobile-contacts", "/tmp/glass-bi-contact-mobile")),
};
const raw = Object.fromEntries(Object.entries(inputPaths).map(([name, path]) => [name, json(path)]));
const SOURCE_BASE = raw.desktop.sourceBase;
const manifestPath = join(REPO, raw.desktop.manifestPath);

for (const [name, run] of Object.entries(raw)) {
    if (run.sourceBase !== SOURCE_BASE) throw new Error(`${name} source base diverges`);
    if (!Array.isArray(run.rows) || run.rows.length === 0) throw new Error(`${name} has no route rows`);
    if (run.manifestSha256 !== raw.desktop.manifestSha256) throw new Error(`${name} manifest digest diverges`);
}
if (fileSha(manifestPath) !== raw.desktop.manifestSha256) throw new Error("capture manifest digest no longer matches the bound source tree");

const normalizeRow = (row) => ({
    kind: row.kind,
    category: row.category ?? null,
    id: row.id ?? null,
    title: row.title ?? null,
    requestedPath: row.route,
    actualPath: row.metrics.pathname,
    redirected: row.route !== row.metrics.pathname,
    manifestLine: row.manifestLine ?? null,
    observedAt: row.observedAt ?? null,
    viewport: row.metrics.viewport,
    document: row.metrics.document,
    h1s: row.metrics.h1s.map((heading) => ({ text: heading.text, visible: heading.visible, clipsViewport: heading.clipsViewport })),
    counts: row.metrics.counts,
    bodyTextLength: row.metrics.bodyTextLength,
    brokenImageCount: row.metrics.brokenImages.length,
    zeroSizeCanvasCount: row.metrics.canvases.filter((canvas) => canvas.zeroSize).length,
    errorSignals: row.metrics.errorSignals,
    screenshot: { bytes: row.screenshot.bytes, sha256: row.screenshot.sha256 },
});

const summarizeRun = (run) => {
    const rows = run.rows.map(normalizeRow);
    const redirects = rows.filter((row) => row.redirected);
    return {
        runId: run.runId,
        completedAt: run.completedAt,
        environment: run.environment ?? null,
        expectedRoutes: run.expectedRoutes ?? rows.length,
        routeCount: rows.length,
        kindCounts: countBy(rows, (row) => row.kind),
        directRouteCount: rows.length - redirects.length,
        redirectCount: redirects.length,
        redirectRows: redirects.map((row) => ({ requestedPath: row.requestedPath, actualPath: row.actualPath, kind: row.kind })),
        renderedMainCount: rows.filter((row) => row.counts.main > 0 && row.bodyTextLength > 0).length,
        horizontalOverflowCount: rows.filter((row) => row.document.horizontalOverflow).length,
        brokenImageRouteCount: rows.filter((row) => row.brokenImageCount > 0).length,
        zeroSizeCanvasRouteCount: rows.filter((row) => row.zeroSizeCanvasCount > 0).length,
        missingH1Rows: rows.filter((row) => row.h1s.length === 0).map((row) => row.requestedPath),
        screenshotCount: rows.filter((row) => row.screenshot.bytes > 0 && /^[0-9a-f]{64}$/.test(row.screenshot.sha256)).length,
        maxOffViewportInteractives: Math.max(...rows.map((row) => row.counts.offViewportInteractives)),
        maxUnnamedInteractives: Math.max(...rows.map((row) => row.counts.unnamedInteractives)),
        rows,
    };
};

const runs = {
    desktop: summarizeRun(raw.desktop),
    mobile: summarizeRun(raw.mobile),
    extra: summarizeRun(raw.extra),
};
const compatibilityRedirects = runs.desktop.redirectRows.filter((row) => row.requestedPath !== "/");
const relocatedRedirects = runs.extra.rows.filter((row) => row.kind === "relocated-redirect").map((row) => ({ requestedPath: row.requestedPath, actualPath: row.actualPath }));
const negativeRoute = runs.extra.rows.find((row) => row.kind === "negative-control");
const warningSignatures = Object.entries(Object.groupBy(raw.desktop.rows[0].console ?? [], (entry) => entry.message)).map(([message, entries]) => ({
    level: entries[0].level,
    message,
    count: entries.length,
}));

const contactSheets = Object.entries(contactDirs).flatMap(([viewport, dir]) => readdirSync(dir).filter((name) => /\.jpe?g$/i.test(name)).sort().map((name) => {
    const path = join(dir, name);
    return { viewport, category: name.replace(/\.jpe?g$/i, ""), bytes: statSync(path).size, sha256: fileSha(path) };
}));

